/bin/bash -lc "python - <<'PY'
import numpy as np
cx,cy,f,H=114.5,96,162.,100.
a=np.arctan(176/f);s,c=np.sin(a),np.cos(a)
def unproj(x,y):
 Y=H*(f*c-(y-cy)*s)/((y-cy)*c+f*s); Z=Y*c+H*s
 return np.array([(x-cx)*Z/f,Y,0.])
def proj(P):
 X,Y,z=P;Z=Y*c+(H-z)*s
 return np.array([cx+f*X/Z,cy+f*((H-z)*c-Y*s)/Z])
D=unproj(57.5,90);C=unproj(75.5,81);A=unproj(49.5,74.5);B=A+C-D
print('vertices',A,B,C,D,'edge lengths',np.linalg.norm(A-D),np.linalg.norm(C-D),'cos',np.dot(A-D,C-D)/np.linalg.norm(A-D)/np.linalg.norm(C-D))
for h in [40,43,46,49]:
 print(h,[proj(p+np.array([0,0,h])).round(2) for p in [A,B,C,D]])
print('baseproj',list(map(proj,[A,B,C,D])), 'center',proj((A+B+C+D)/4))
PY"
